UNLOCK TABLES;

--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category_id` int NOT NULL,
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `rating` decimal(3,2) DEFAULT '0.00' COMMENT 'Điểm đánh giá trung bình',
  `features` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `delivery_type` enum('account','email_only','customer_account') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'account' COMMENT 'Loại giao hàng: account = Từ kho, email_only = Lời mời nhóm, customer_account = Tài khoản khách hàng',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` decimal(15,2) NOT NULL,
  `sale_price` decimal(15,2) DEFAULT NULL,
  `stock_quantity` int DEFAULT '0',
  `sold_count` int DEFAULT '0',
  `status` enum('active','inactive','out_of_stock') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `featured` tinyint(1) DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `views` int DEFAULT '0',
  `sort_order` int DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `category_id` (`category_id`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,1,'Netflix Premium','netflix-premium','App, Giải trí, Streaming','<h1>⭐ Chi tiết sản phẩm &amp; Quy trình nhận hàng</h1><h2><strong>1. Hình thức sản phẩm</strong></h2><p>Đây là <strong>tài khoản Netflix Premium (UltraHD)</strong> được tạo sẵn và chia thành nhiều User. Mỗi khách hàng sau khi mua sẽ được cấp <strong>1 User riêng</strong> để sử dụng ổn định.</p><h2><strong>2. Thông tin nhận hàng</strong></h2><p>Ngay sau khi thanh toán, bạn sẽ nhận được:</p><ul><li>Email đăng nhập Netflix</li><li>Mật khẩu</li><li>Số User được cấp</li><li>Mã PIN User (nếu có)</li></ul><h2><strong>3. Thời gian xử lý</strong></h2><p>✔ Ngay lập tức sau khi thanh toán thành công.</p><h2><strong>4. Hình thức giao hàng</strong></h2><p>✔ Thông tin đăng nhập sẽ hiển thị ngay trong đơn hàng.</p><h2><strong>5. Thiết bị hỗ trợ</strong></h2><ul><li>Đăng nhập được trên nhiều thiết bị, <strong>nhưng chỉ xem được 1 thiết bị tại 1 thời điểm</strong> (do là tài khoản share).</li><li>Không hỗ trợ sử dụng với máy chiếu.</li></ul><h2><strong>6. Khu vực sử dụng</strong></h2><p>Sản phẩm <strong>chỉ dùng được tại Việt Nam</strong>, không hoạt động ở nước ngoài.</p><h2><strong>7. Hướng dẫn đăng nhập Netflix</strong></h2><p>Có kèm trong đơn hàng để bạn thao tác nhanh chóng.</p><h1>🛡 Chính sách bảo hành</h1><h3>⏳ Thời gian bảo hành</h3><p><strong>30 ngày</strong> kể từ khi kích hoạt.</p><h3>📌 Nội dung bảo hành</h3><ul><li>Nếu tài khoản gặp lỗi sẽ được <strong>đổi user mới/ngay lập tức</strong>.</li><li>Nếu không còn tài khoản thay thế → <strong>hoàn tiền</strong>.</li></ul><p>👉 Xem chi tiết tại trang <strong>Chính sách bảo hành</strong>.</p><h3>❌ Miễn trừ trách nhiệm</h3><p>Shop sẽ từ chối bảo hành hoặc thu hồi tài khoản nếu khách hàng vi phạm:</p><ul><li>Tự ý đổi email/mật khẩu tài khoản.</li><li>Tự ý thay đổi gói cước hoặc thông tin thanh toán.</li><li>Chia sẻ tài khoản hoặc dùng nhiều hơn 1 thiết bị cùng lúc.</li><li>Sử dụng tài khoản ở <strong>ngoài Việt Nam</strong>.</li></ul><h1>❓ Câu hỏi thường gặp (FAQ)</h1><h3>1. Netflix Premium là gì?</h3><p>Là gói xem phim chất lượng cao nhất của Netflix với kho nội dung lớn, tốc độ nhanh, hỗ trợ 4K và phụ đề tiếng Việt.</p><h3>2. Cách mua Netflix?</h3><p>Nhấn <strong>Mua Ngay</strong>, chọn thanh toán bằng Momo / Ngân hàng / Số dư. Tài khoản được giao tự động.</p><h3>3. Khi lỗi tài khoản thì sao?</h3><p>Shop hỗ trợ <strong>đổi user mới ngay</strong>, hoặc hoàn tiền nếu không còn tài khoản thay thế.</p><h3>4. Gói Premium có gì?</h3><ul><li>Xem phim <strong>4K UltraHD</strong></li><li>Tải phim xem offline</li><li>Nội dung đa dạng, phụ đề tiếng Việt</li><li>Xem trên TV, mobile, PC</li></ul><h3>5. Có dùng trên nhiều thiết bị không?</h3><p>Đăng nhập thoải mái, nhưng <strong>chỉ xem được 1 thiết bị tại 1 thời điểm</strong>.</p><h3>6. Có hỗ trợ xem 4K không?</h3><p>Có, miễn là thiết bị và tốc độ mạng của bạn đủ tiêu chuẩn. Trên điện thoại, chất lượng tối đa là <strong>1080p</strong>.</p><h3>7. Không tìm thấy một số phim?</h3><p>Một số nội dung chỉ có ở từng khu vực. Muốn xem cần dùng <strong>VPN đổi IP</strong> sang khu vực tương ứng.</p><h3>8. Có chỉnh độ phân giải không?</h3><p>Không. Netflix tự điều chỉnh theo tốc độ mạng.</p><h3>9. Trình duyệt nào xem được 4K?</h3><ul><li>Microsoft Edge</li><li>Safari (macOS 11 trở lên)</li></ul><h3>10. Bị lỗi tài khoản phải làm sao?</h3><p>Liên hệ CSKH (8h30 – 23h) để được hỗ trợ ngay. Ngoài giờ, truy cập trang bảo hành.</p><h3>11. Có thay đổi ngôn ngữ tài khoản được không?</h3><p>Có thể đổi tự do.</p><h3>12. Có chỉnh kích cỡ/màu sắc phụ đề không?</h3><p>Có hỗ trợ tùy chỉnh đầy đủ.</p><h3>13. Đã đổi ngôn ngữ nhưng không có phụ đề tiếng Việt?</h3><p>Phụ đề phụ thuộc vào từng nội dung, không phải phim nào cũng có.</p><h3>14. Có chơi game Netflix được không?</h3><p>Không. Netflix Game chưa hỗ trợ tại Việt Nam.</p><h3>15. Có tải phim xem offline được không?</h3><p>Có, nhưng cần mở mạng <strong>ít nhất 1 lần mỗi 7 ngày</strong>.</p><h3>16. Báo quá tải thiết bị phải làm sao?</h3><p>Do tài khoản share nên đôi khi bị quá tải. Liên hệ CSKH giờ làm việc để đổi user.</p><h3>17. Có gia hạn tài khoản cũ được không?</h3><p>Chưa hỗ trợ gia hạn. Khi hết hạn bạn cần mua tài khoản mới.</p><h3>18. Ở nước ngoài có dùng được không?</h3><p>Có. Tài khoản có thể hoạt động ở nước ngoài</p>',0.00,'<p>Xem 4K HDR Không quảng cáo Tải offline</p>','account','',135000.00,120000.00,50,2,'active',1,'2025-10-31 03:48:59','2025-11-20 19:03:07',0,0),(2,15,'Spotify Family - Slot Tham Gia','spotify-family-slot','Giải trí','<h1>⭐ Giới thiệu sản phẩm Spotify Premium Family</h1><h2>📌 Spotify Family là gì?</h2><p><strong>Spotify Premium Family</strong> là gói nghe nhạc cao cấp cho gia đình với 6 tài khoản thành viên, sử dụng độc lập và không ảnh hưởng lẫn nhau.</p><p> Khi tham gia Family, bạn sẽ được hưởng toàn bộ lợi ích của gói Premium:</p><ul><li>Nghe nhạc chất lượng cao</li><li>Không quảng cáo</li><li>Tải nhạc offline</li><li>Chuyển bài nhanh, không giới hạn</li><li>Playlist cá nhân – đề xuất nhạc thông minh</li></ul><h1>⭐ Chi tiết sản phẩm &amp; Quy trình nhận hàng</h1><h3><strong>1. Hình thức sản phẩm</strong></h3><ul><li>Đây là <strong>lời mời vào Family Spotify Premium</strong>.</li><li>Bạn <strong>không cần cung cấp mật khẩu</strong>, chỉ cần <strong>Email tài khoản Spotify</strong> để nhận lời mời Family.</li><li>Tài khoản sau khi tham gia sẽ trở thành <strong>Premium đầy đủ tính năng</strong>.</li></ul><h3><strong>2. Cách sử dụng</strong></h3><ol><li>Bạn gửi email Spotify (hoặc đăng ký email mới tùy thích)</li><li>Shop gửi <strong>lời mời Family Premium</strong></li><li>Bạn chấp nhận → tài khoản trở thành Premium ngay</li></ol><h3><strong>3. Thời gian xử lý</strong></h3><p>✔ 1–5 phút sau khi thanh toán.</p><h3><strong>4. Thông tin nhận hàng</strong></h3><ul><li>Link/lời mời Family Spotify</li><li>Hướng dẫn tham gia</li><li>CSKH hỗ trợ kỹ thuật trong toàn bộ thời gian bảo hành</li></ul><h3><strong>5. Thiết bị hỗ trợ Spotify</strong></h3><ul><li>Android / iO